"""Generates docs/TASK_A_REPORT.md from reports/taskA/*.json + test_predictions.csv + confusion csv. All numbers come from the saved results."""
import csv, json, collections
import numpy as np
from common_a import *

def J(n): return json.loads((REPORTS / n).read_text())
def row(name, rep, split="test"):
    r, a, i = rep[split]["real"], rep[split]["all"], rep[split].get("real_indian", {})
    return f"| {name} | {r['accuracy']:.3f} | {r['macro_f1']:.3f} ({r['macro_f1_ci95'][0]:.2f}-{r['macro_f1_ci95'][1]:.2f}) | {i.get('accuracy', float('nan')):.3f} | {a['accuracy']:.3f} | {rep[split]['synthetic']['accuracy']:.3f} | {r['ece']:.3f} |"

if __name__ == "__main__":
    fu = J("fusion.json"); tx = J("text_baseline.json"); out = []
    tr, va, te = load("train"), load("val"), load("test")
    cnt = lambda rows: (len(rows), sum(not r["synthetic"] for r in rows))
    out += ["# Task A report: expense-category classification", "", f"Generated by `scripts/taskA/t7_report.py` from `reports/taskA/*.json`. Labels: {len(LABELS)} (`{'`, `'.join(LABELS)}`).", "",
            "## 1. Data and protocol", f"* Train {cnt(tr)[0]} ({cnt(tr)[1]} real) / validation {cnt(va)[0]} ({cnt(va)[1]} real) / test {cnt(te)[0]} ({cnt(te)[1]} real). Splits are by document group (template / merchant / near-duplicate family) - see docs/DATASET.md.",
            "* Model selection (C, epochs, fusion weights, temperatures, routing threshold) uses **validation only**; the test set is evaluated once per model after training.",
            "* Headline metric: **real-only** test accuracy / macro-F1 (synthetic bills are templated and score ~1.0 for every model, so they say nothing about real-world accuracy). CI = 95% bootstrap over document groups.",
            "* Disclosure: before LayoutLMv3 finished I ran the fusion script once on text + image only as a code test and saw its test score (real acc 0.912 / macro-F1 0.850); it was not used to choose anything. The final three-model fusion below was selected on validation NLL only.",
            "* `rent` has no real documents: it is trained and checked on synthetic bills only, so its real-world accuracy is **unknown**.", "",
            "## 2. Results (test set, real documents unless stated)", "", "| model | real acc | real macro-F1 (95% CI) | real-Indian acc | all acc | synthetic acc | ECE (real, calibrated) |", "|---|---:|---:|---:|---:|---:|---:|"]
    names = {"text": "TF-IDF + LogReg (OCR text)", "image": "ConvNeXt-Tiny (image)", "layoutlm": "LayoutLMv3-base (text+layout+image)"}
    for k in fu["models"]: out.append(row(names[k], fu["single_models"][k]))
    out.append(row("**Calibrated fusion** (" + " + ".join(f"{k} {fu['weights'][k]:.1f}" for k in fu["models"]) + ")", fu["fused"]))
    out += ["", f"Per-model temperatures (fit on val): {', '.join(f'{k} {v:.2f}' for k, v in fu['temperatures'].items())}; fused temperature {fu['fused_temperature']:.2f}.", "",
            "### Validation results (used for selection)", "", "| model | real acc | real macro-F1 | all acc |", "|---|---:|---:|---:|"]
    for k in fu["models"]:
        v = fu["single_models"][k]["val"]; out.append(f"| {names[k]} | {v['real']['accuracy']:.3f} | {v['real']['macro_f1']:.3f} | {v['all']['accuracy']:.3f} |")
    v = fu["fused"]["val"]; out.append(f"| fusion | {v['real']['accuracy']:.3f} | {v['real']['macro_f1']:.3f} | {v['all']['accuracy']:.3f} |")
    # label cleanup effect + ablation + CV
    out += ["", "## 3. Label cleanup, synthetic-data ablation, cross-validation (text model)",
            "* **Label audit** (group-OOF text-model disagreements, 85 real documents reviewed by eye + OCR text, plus every rule-labelled transport/hotel/medical/fuel/train document): 90 corrections in `datasets/metadata/label_overrides.json` (e.g. Subway sandwiches, Cyberport IT store, McDonald's and car-rental contracts mislabelled by regex; 39 Indian ReceiptBench 'purchase' receipts that were restaurant bills). Same text model: validation real macro-F1 **0.789 -> 0.868**, test real macro-F1 **0.806 -> 0.831** (accuracy 0.863 -> 0.883).",
            f"* **Synthetic ablation** (text model trained on real data only): test real acc {tx['ablation_real_only_train']['test']['real']['accuracy']:.3f} / macro-F1 {tx['ablation_real_only_train']['test']['real']['macro_f1']:.3f} vs {tx['test']['real']['accuracy']:.3f} / {tx['test']['real']['macro_f1']:.3f} with synthetic added; real-Indian acc {tx['ablation_real_only_train']['test']['real_indian']['accuracy']:.3f} vs {tx['test']['real_indian']['accuracy']:.3f}. Synthetic data helps real accuracy only marginally; its job is to give `rent` and the thin classes any training signal at all (the real-only model scores {tx['ablation_real_only_train']['test']['synthetic']['accuracy']:.2f} on synthetic bills).",
            f"* **Group 5-fold CV on train+val** (text model): real acc {tx['group_cv5_trainval']['real']['accuracy']:.3f}, real macro-F1 {tx['group_cv5_trainval']['real']['macro_f1']:.3f} (CI {tx['group_cv5_trainval']['real']['macro_f1_ci95'][0]:.2f}-{tx['group_cv5_trainval']['real']['macro_f1_ci95'][1]:.2f}); real-Indian acc {tx['group_cv5_trainval']['real_indian']['accuracy']:.3f}.", ""]
    # per class
    pc = fu["fused"]["test"]["real"]["per_class"]; pcs = fu["fused"]["test"]["all"]["per_class"]
    out += ["## 4. Per-class results (fusion, test)", "", "| class | real n | real P | real R | real F1 | all-docs F1 | note |", "|---|---:|---:|---:|---:|---:|---|"]
    for l in LABELS:
        r = pc.get(l); a = pcs.get(l, {})
        note = "synthetic only" if not r else ("n<10: unreliable" if r["n"] < 10 else "")
        out.append(f"| {l} | {r['n'] if r else 0} | {r['precision'] if r else '-'} | {r['recall'] if r else '-'} | {r['f1'] if r else '-'} | {a.get('f1', '-')} | {note} |")
    # confusions
    P = list(csv.DictReader(open(REPORTS / "test_predictions.csv"))); err = collections.Counter((p["true"], p["pred"]) for p in P if p["correct"] == "0" and p["synthetic"] == "False")
    out += ["", "### Most frequent real-document errors (true -> predicted)", ""]
    for (a, b), n in err.most_common(10): out.append(f"* {a} -> {b}: {n}  (e.g. {', '.join(p['document_id'] for p in P if p['true']==a and p['pred']==b and p['synthetic']=='False')[:3 * 40] if False else ', '.join([p['document_id'] for p in P if p['true']==a and p['pred']==b and p['synthetic']=='False'][:2])})")
    # routing
    ro = fu["routing"]
    out += ["", "## 5. Confidence and routing to HR", f"* Rule: auto-process when fused confidence >= **tau = {ro['tau']}** (smallest threshold giving >= {ro['target_precision']:.0%} precision on validation real documents); everything else goes to HR.",
            f"* Validation, real: auto-coverage {ro['val']['real']['auto_coverage']:.1%}, auto-precision {ro['val']['real']['auto_precision']}. **Test, real: auto-coverage {ro['test']['real']['auto_coverage']:.1%}, auto-precision {ro['test']['real']['auto_precision']}, {ro['test']['real']['sent_to_hr']} of {ro['test']['real']['n']} sent to HR.** Test precision is the honest number.",
            "", "Risk-coverage on test real documents:", "", "| threshold | coverage | precision of auto-processed |", "|---:|---:|---:|"]
    for r in fu["risk_coverage_test_real"][::2]: out.append(f"| {r['threshold']} | {r['coverage']} | {r['precision']} |")
    out += ["", "## 6. Limitations", "* Real test sets are small for the weak classes (see per-class n); read per-class numbers with the CIs in `reports/taskA/fusion.json`.",
            "* Calibration and tau are fit on a small validation set; re-fit when more real data arrives. Tau gives ~95% precision on validation, test is reported above.",
            "* `rent` is synthetic only. Hotel / flight / bus / taxi are mostly foreign real documents; real Indian coverage is in docs/REAL_DATA_ACQUISITION_2026-10-04.md.",
            "* LayoutLMv3-base weights are CC-BY-NC-SA-4.0 (non-commercial); ConvNeXt (timm) is Apache-2.0. The data has unverified rights for part of the real documents: keep models/data internal.",
            "* OCR errors (handwriting, tilted photos) propagate to the text and layout models; the image model is the fallback when OCR is empty.",
            "", "## 7. Reproduce", "```bash", "python scripts/taskA/build_cache.py            # resized image cache", "python scripts/taskA/t1_text_baseline.py", "python scripts/taskA/t5_label_audit.py        # contact sheets for visual review", "python scripts/taskA/t6_apply_label_review.py  # then: python scripts/create_splits.py && python scripts/validate_dataset.py",
            "python scripts/taskA/t2_image_convnext.py      # GPU, ~17 min", "python scripts/taskA/t3_layoutlmv3.py          # GPU, ~55 min (micro-batch 2 x accumulation 8 on a 6 GB card)", "python scripts/taskA/t4_fusion_calibration.py  # fusion, temperatures, routing threshold, test predictions", "python scripts/taskA/t7_report.py", "python scripts/taskA/predict.py bill.jpg      # inference: OCR -> models -> label, confidence, auto/hr_review", "```",
            "", "Artifacts: `models/taskA/` (text_lr.joblib, convnext_tiny.pt, layoutlmv3.pt, fusion.json, logits/probs), `reports/taskA/` (all metrics, confusion matrix, test predictions, audit sheets)."]
    (ROOT / "docs/TASK_A_REPORT.md").write_text("\n".join(out)); print("wrote docs/TASK_A_REPORT.md", len(out), "lines")
